1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	const PROCESSING_FEE = 5;
42	
43	const CURSE_SURCHARGE = 0.5;
44	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
45	const LOYALTY_DISCOUNT = -0.2;
46	const FOLLOW_UP_CONTRACT_DISCOUNT = -0.15;
47	/** Levied on every quote, not only the customer's first — see the policy-wide modifier rules. */
48	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
49	
50	/** The MHPCO price list; only the types pinned down by tests so far. */
51	const BASE_PREMIUMS: Record<string, number | undefined> = {
52	  sword: 100,
53	  amulet: 60,
54	  staff: 80,
55	  potion: 40,
56	  rune: 25,
57	  moonstone: 25,
58	};
59	
60	/** Keeps binary floating-point drift from tipping an exact amount over a rounding boundary. */
61	const withoutFloatNoise = (amount: number): number => Number(amount.toFixed(6));
62	
63	/** Premiums are rounded in the MHPCO's favour: up to the next whole G. */
64	const roundUpToWholeG = (amount: number): number => Math.ceil(withoutFloatNoise(amount));
65	
66	const basePremiumFor = (item: Item): number => {
67	  const basePremium = BASE_PREMIUMS[item.type];
68	  if (basePremium === undefined) throw new Error(`Unknown item type: ${item.type}`);
69	  return basePremium;
70	};
71	
72	const sumOf = <T>(values: T[], amountOf: (value: T) => number): number =>
73	  values.reduce((total, value) => total + amountOf(value), 0);
74	
75	/** A building block of 3 alike components is offered at a special base premium. */
76	const BLOCK_SIZE = 3;
77	const BLOCK_BASE_PREMIUM = 60;
78	
79	const alikeComponentGroups = (items: Item[]): Item[][] => [
80	  ...items
81	    .reduce(
82	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
83	      new Map<string, Item[]>(),
84	    )
85	    .values(),
86	];
87	
88	const basePremiumForGroup = (group: Item[]): number =>
89	  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sumOf(group, basePremiumFor);
90	
91	const HIGH_ENCHANTMENT_THRESHOLD = 5;
92	
93	const isCursed = (item: Item): boolean => item.cursed === true;
94	
95	const isHighlyEnchanted = (item: Item): boolean =>
96	  item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_THRESHOLD;
97	
98	/**
99	 * A modifier raises or lowers the amount it applies to by `rate`, but only for
100	 * subjects it applies to. Modifiers that apply stack additively.
101	 */
102	interface Modifier<Subject> {
103	  appliesTo: (subject: Subject) => boolean;
104	  rate: number;
105	}
106	
107	const combinedRateOf = <Subject>(
108	  modifiers: Modifier<Subject>[],
109	  subject: Subject,
110	): number => sumOf(modifiers, ({ appliesTo, rate }) => (appliesTo(subject) ? rate : 0));
111	
112	/** Item-specific modifiers are levied on the affected item's own base premium. */
113	const ITEM_MODIFIERS: Modifier<Item>[] = [
114	  { appliesTo: isCursed, rate: CURSE_SURCHARGE },
115	  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE },
116	];
117	
118	const itemSurchargeFor = (item: Item): number =>
119	  basePremiumFor(item) * combinedRateOf(ITEM_MODIFIERS, item);
120	
121	const LOYALTY_THRESHOLD_YEARS = 2;
122	
123	/**
124	 * The circumstances a single quote is issued under: who is being quoted, and
125	 * where this contract falls in their history with the MHPCO. Policy-wide
126	 * modifiers are decided from this alone.
127	 */
128	interface QuoteContext {
129	  customer: Customer;
130	  isFollowUpContract: boolean;
131	}
132	
133	const isLongStanding = ({ customer }: QuoteContext): boolean =>
134	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
135	
136	const followsAnEarlierContract = ({ isFollowUpContract }: QuoteContext): boolean =>
137	  isFollowUpContract;
138	
139	const appliesToEveryQuote = (): boolean => true;
140	
141	/** Policy-wide modifiers are levied on the whole policy's base premium. */
142	const POLICY_MODIFIERS: Modifier<QuoteContext>[] = [
143	  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT },
144	  { appliesTo: appliesToEveryQuote, rate: INITIAL_ASSESSMENT_SURCHARGE },
145	  { appliesTo: followsAnEarlierContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT },
146	];
147	
148	/**
149	 * Item-specific modifiers are levied on the affected item's own base premium,
150	 * while policy-wide modifiers are levied on the policy base premium — the sum
151	 * of the item base premiums, before any item surcharge is added.
152	 */
153	const quote = (step: QuoteStep, context: QuoteContext): StepResult => {
154	  const policyBasePremium = sumOf(alikeComponentGroups(step.items), basePremiumForGroup);
155	  const itemSurcharges = sumOf(step.items, itemSurchargeFor);
156	  const policyModifiers = policyBasePremium * combinedRateOf(POLICY_MODIFIERS, context);
157	  return {
158	    premium: roundUpToWholeG(
159	      policyBasePremium + itemSurcharges + policyModifiers + PROCESSING_FEE,
160	    ),
161	  };
162	};
163	
164	const runStep = (step: Step, context: QuoteContext): StepResult => {
165	  if (step.op === "quote") return quote(step, context);
166	  throw new Error(`Unsupported step: ${step.op}`);
167	};
168	
169	/**
170	 * Steps are not independent: a quote's premium depends on whether an earlier
171	 * quote in the same scenario already established a contract, so each step is
172	 * run against the history the steps before it left behind.
173	 */
174	export const runScenario = (scenario: Scenario): ScenarioResult => {
175	  let hasQuoted = false;
176	  const results = scenario.steps.map((step) => {
177	    const result = runStep(step, {
178	      customer: scenario.customer,
179	      isFollowUpContract: hasQuoted,
180	    });
181	    if (step.op === "quote") hasQuoted = true;
182	    return result;
183	  });
184	  return { results };
185	};
